-- 0040_seed_exercises_kettlebell_trx_bands.sql
-- Semilla: kettlebell, TRX y gomas elásticas (clean, snatch, turkish get-up, remo TRX, pull apart…) con su técnica. Requiere 0026.
-- GENERADO por scripts/seed-sql.ts a partir de supabase/seed/*.json. No editar a mano.
-- Idempotente: se puede ejecutar varias veces.

  id, name, aliases, category, tracking_type, equipment, is_unilateral, is_compound,
  default_rest_s, technique_notes
) values
  ('kb_clean', 'Cargada con kettlebell', array['kettlebell clean', 'kb clean', 'clean con kettlebell', 'cargada kb']::text[], 'functional', 'weight_reps', array['kettlebell']::text[], true, true, 90, 'Bisagra de cadera que lleva la kettlebell a la posición de rack sin golpear el antebrazo.'),
  ('kb_snatch', 'Arrancada con kettlebell', array['kettlebell snatch', 'kb snatch', 'snatch con kettlebell', 'arrancada kb']::text[], 'functional', 'weight_reps', array['kettlebell']::text[], true, true, 120, 'Del balanceo a la vertical por encima de la cabeza en un solo movimiento.'),
  ('kb_turkish_get_up', 'Turkish get-up', array['turkish get up', 'tgu', 'levantada turca', 'get-up turco', 'turkish getup']::text[], 'functional', 'weight_reps', array['kettlebell', 'dumbbell']::text[], true, true, 120, 'De tumbado a de pie con la kettlebell arriba y la mirada en ella; despacio.'),
  ('kb_press', 'Press con kettlebell', array['kettlebell press', 'kb press', 'press militar con kettlebell', 'kettlebell military press']::text[], 'strength', 'weight_reps', array['kettlebell']::text[], true, true, 90, 'Desde el rack, empuja hacia arriba con el antebrazo vertical y el glúteo apretado.'),
  ('kb_one_arm_swing', 'Kettlebell swing a una mano', array['one arm kettlebell swing', 'single arm swing', 'swing a una mano', 'kb swing unilateral']::text[], 'functional', 'weight_reps', array['kettlebell']::text[], true, true, 90, 'Igual que el swing, con una mano: el core evita que el tronco gire.'),
  ('kb_halo', 'Halo con kettlebell', array['kettlebell halo', 'halo', 'kb halo', 'círculos con kettlebell']::text[], 'mobility', 'reps', array['kettlebell', 'plate']::text[], false, false, 45, 'Rodea la cabeza con la kettlebell boca abajo, cerca de la cabeza; ligero.'),
  ('kb_deadlift', 'Peso muerto con kettlebell', array['kettlebell deadlift', 'kb deadlift', 'peso muerto kb', 'sumo kettlebell']::text[], 'strength', 'weight_reps', array['kettlebell']::text[], false, true, 90, 'Kettlebell entre los pies; bisagra de cadera con la espalda neutra.'),
  ('kb_high_pull', 'Tirón alto con kettlebell', array['kettlebell high pull', 'sumo high pull', 'kb high pull', 'tirón al mentón con kettlebell']::text[], 'functional', 'weight_reps', array['kettlebell']::text[], false, true, 90, 'Desde abajo, extiende la cadera y tira de la kettlebell hasta el pecho con los codos altos.'),
  ('trx_row', 'Remo en TRX', array['trx row', 'suspension row', 'remo en suspensión', 'remo con anillas', 'ring row']::text[], 'strength', 'reps', array['trx', 'rings']::text[], false, true, 75, 'Cuerpo recto inclinado; cuanto más horizontal, más difícil.'),
  ('trx_chest_press', 'Press de pecho en TRX', array['trx chest press', 'flexiones en trx', 'suspension push-up', 'press en suspensión']::text[], 'strength', 'reps', array['trx']::text[], false, true, 75, 'De espaldas al anclaje, inclinado hacia delante, baja como en una flexión.'),
  ('trx_squat', 'Sentadilla en TRX', array['trx squat', 'sentadilla asistida', 'suspension squat']::text[], 'strength', 'reps', array['trx']::text[], false, true, 60, 'Agarrado a las asas para equilibrarte; baja profundo con el torso erguido.'),
  ('trx_hamstring_curl', 'Curl femoral en TRX', array['trx hamstring curl', 'curl de isquios en suspensión', 'trx leg curl']::text[], 'strength', 'reps', array['trx']::text[], false, false, 60, 'Tumbado con los talones en las asas, sube la cadera y lleva los talones al glúteo.'),
  ('trx_pike', 'Pike en TRX', array['trx pike', 'pica en trx', 'suspension pike', 'navaja en trx']::text[], 'strength', 'reps', array['trx']::text[], false, true, 60, 'En plancha con los pies en las asas, sube la cadera en V con las piernas rectas.'),
  ('trx_y_raise', 'Elevación en Y en TRX', array['trx y fly', 'trx y raise', 'y en suspensión', 'trx y']::text[], 'strength', 'reps', array['trx']::text[], false, false, 60, 'Inclinado atrás, sube los brazos estirados en forma de Y.'),
  ('trx_biceps_curl', 'Curl de bíceps en TRX', array['trx biceps curl', 'curl en suspensión', 'trx curl']::text[], 'strength', 'reps', array['trx']::text[], false, false, 60, 'Inclinado atrás, codos a la altura de los hombros; lleva las manos a la frente.'),
  ('band_pull_apart', 'Pull apart con goma', array['band pull apart', 'pull aparts', 'aperturas con goma', 'separación de goma']::text[], 'strength', 'reps', array['band']::text[], false, false, 45, 'Brazos estirados al frente: abre la goma hasta el pecho juntando los omóplatos.'),
  ('banded_lateral_walk', 'Paso lateral con goma', array['lateral band walk', 'monster walk', 'banded side steps', 'pasos laterales con mini band', 'cangrejo con goma']::text[], 'strength', 'reps', array['band']::text[], false, false, 45, 'Goma en las rodillas o tobillos, semisentadilla y pasos laterales sin juntar los pies.'),
  ('band_row', 'Remo con goma', array['band row', 'resistance band row', 'remo con banda elástica', 'remo sentado con goma']::text[], 'strength', 'reps', array['band']::text[], false, true, 60, 'Goma anclada al frente o a los pies; tira llevando los codos atrás.'),
  ('band_external_rotation', 'Rotación externa con goma', array['band external rotation', 'rotación externa de hombro', 'manguito rotador', 'external rotation']::text[], 'strength', 'reps', array['band', 'cable']::text[], true, false, 45, 'Codo pegado al costado a 90°; gira el antebrazo hacia fuera. Para el manguito rotador.'),
  ('band_kickback', 'Patada de glúteo con goma', array['band kickback', 'glute kickback band', 'patada trasera con goma', 'patada de burro con goma']::text[], 'strength', 'reps', array['band', 'mat']::text[], true, false, 45, 'A cuatro patas o de pie, lleva la pierna atrás contra la goma apretando el glúteo.')
on conflict (id) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  category = excluded.category,
  tracking_type = excluded.tracking_type,
  equipment = excluded.equipment,
  is_unilateral = excluded.is_unilateral,
  is_compound = excluded.is_compound,
  default_rest_s = excluded.default_rest_s,
  technique_notes = excluded.technique_notes
where public.exercises.owner_id is null;

-- Músculos: se reescriben para que la semilla sea la fuente de verdad.
delete from public.exercise_muscles where exercise_id in ('kb_clean', 'kb_snatch', 'kb_turkish_get_up', 'kb_press', 'kb_one_arm_swing', 'kb_halo', 'kb_deadlift', 'kb_high_pull', 'trx_row', 'trx_chest_press', 'trx_squat', 'trx_hamstring_curl', 'trx_pike', 'trx_y_raise', 'trx_biceps_curl', 'band_pull_apart', 'banded_lateral_walk', 'band_row', 'band_external_rotation', 'band_kickback');

on conflict (exercise_id, muscle_id) do update set role = excluded.role;

-- Técnica (pasos clave y errores típicos).
update public.exercises e set
  technique_steps = v.steps,
  technique_mistakes = v.mistakes
from (values
  ('kb_clean', array['Kettlebell entre los pies; cógela con una mano haciendo bisagra de cadera.', 'Balancéala entre las piernas y extiende la cadera con fuerza.', 'Mantén el codo cerca del cuerpo y deja que la kettlebell rodee la mano hasta el rack, junto al pecho.', 'Vuelve a bajarla con control al balanceo siguiente.']::text[], array['Tirar con el brazo como en un curl.', 'Separar el codo: la kettlebell golpea el antebrazo.', 'Redondear la espalda al bajar.']::text[]),
  ('kb_snatch', array['Empieza como un swing a una mano con la espalda neutra.', 'Extiende la cadera con fuerza y lleva la kettlebell pegada al cuerpo hacia arriba.', 'Mete la mano por debajo del asa al final para que la kettlebell gire suave y no golpee.', 'Bloquea el brazo arriba un segundo y baja con control al balanceo.']::text[], array['Dejar que la kettlebell golpee la muñeca arriba.', 'Tirar con el brazo en vez de con la cadera.', 'Arquear la lumbar arriba.']::text[]),
  ('kb_turkish_get_up', array['Túmbate con la kettlebell arriba en una mano (brazo estirado) y esa rodilla doblada.', 'Apóyate en el codo y luego en la mano contraria mientras miras la kettlebell.', 'Sube la cadera, pasa la pierna estirada por debajo hasta apoyar la rodilla y ponte de pie.', 'Deshaz los pasos en orden inverso hasta tumbarte.']::text[], array['Doblar el brazo de la kettlebell.', 'Ir deprisa saltándose posiciones.', 'Dejar de mirar la kettlebell.']::text[]),
  ('kb_press', array['Coloca la kettlebell en rack: junto al pecho, con el asa en la palma y el codo abajo.', 'Aprieta glúteos y abdomen.', 'Empuja hacia arriba hasta estirar el brazo, con el bíceps junto a la oreja.', 'Baja controlando al rack.']::text[], array['Inclinar el tronco hacia el lado contrario.', 'Arquear la lumbar.', 'Doblar la muñeca hacia atrás.']::text[]),
  ('kb_one_arm_swing', array['Kettlebell un poco delante; cógela con una mano haciendo bisagra de cadera.', 'Llévala entre las piernas y extiende la cadera con fuerza.', 'Deja que suba hasta la altura del pecho sin tirar con el hombro.', 'Deja que caiga y vuelve a la bisagra; cambia de mano al acabar.']::text[], array['Girar el tronco hacia el lado de la kettlebell.', 'Hacer sentadilla en vez de bisagra.', 'Subir con el brazo.']::text[]),
  ('kb_halo', array['Sujeta la kettlebell por los lados del asa, boca abajo, delante del pecho.', 'Llévala alrededor de la cabeza, cerca del cuello y con los codos doblados.', 'Mantén el abdomen firme para que el tronco no se mueva.', 'Alterna el sentido en cada repetición.']::text[], array['Alejar mucho la kettlebell de la cabeza.', 'Arquear la espalda al pasar por detrás.', 'Usar un peso que obliga a mover el cuerpo.']::text[]),
  ('kb_deadlift', array['Ponte con la kettlebell entre los pies, a la altura del empeine.', 'Lleva la cadera atrás con las rodillas algo flexionadas y coge el asa con las dos manos.', 'Tensa la espalda y sube empujando el suelo hasta quedar erguido.', 'Baja por el mismo camino.']::text[], array['Redondear la espalda.', 'Kettlebell demasiado adelantada.', 'Echarse hacia atrás arriba.']::text[]),
  ('kb_high_pull', array['Con los pies abiertos y la kettlebell entre ellos, cógela con las dos manos.', 'Extiende la cadera con fuerza y aprovecha el impulso para tirar.', 'Lleva los codos altos y fuera hasta que el asa llegue a la altura del pecho.', 'Baja controlando y repite.']::text[], array['Tirar solo con los brazos.', 'Subir el asa por encima de la barbilla.', 'Redondear la espalda al bajar.']::text[]),
  ('trx_row', array['Coge las asas con las palmas enfrentadas y camina hacia delante hasta inclinarte atrás.', 'Cuerpo recto de talones a cabeza y brazos estirados.', 'Tira llevando el pecho hacia las manos y juntando los omóplatos.', 'Baja despacio hasta estirar los brazos.']::text[], array['Dejar caer la cadera.', 'Encoger los hombros.', 'Soltarse hacia atrás sin control.']::text[]),
  ('trx_chest_press', array['De espaldas al anclaje, coge las asas con los brazos estirados delante del pecho.', 'Inclínate hacia delante con el cuerpo recto.', 'Baja doblando los codos hasta que las manos queden junto al pecho.', 'Empuja hasta estirar los brazos.']::text[], array['Dejar que las asas se abran hacia fuera.', 'Hundir la cadera.', 'Inclinarse tanto que no se controla.']::text[]),
  ('trx_squat', array['De cara al anclaje, coge las asas con los brazos casi estirados.', 'Pies a la anchura de los hombros.', 'Baja en sentadilla tan profundo como puedas con el torso erguido.', 'Sube empujando con las piernas; los brazos solo equilibran.']::text[], array['Tirar con los brazos para subir.', 'Talones despegados.', 'Rodillas hacia dentro.']::text[]),
  ('trx_hamstring_curl', array['Túmbate boca arriba con los talones en las asas, bajo el anclaje.', 'Sube la cadera hasta alinear el cuerpo.', 'Lleva los talones hacia los glúteos sin bajar la cadera.', 'Estira las piernas despacio.']::text[], array['Dejar caer la cadera al doblar las rodillas.', 'Ir con impulso.', 'Arquear la lumbar.']::text[]),
  ('trx_pike', array['Pon los pies en las asas y colócate en plancha alta con las manos bajo los hombros.', 'Sube la cadera hacia el techo con las piernas estiradas, formando una V invertida.', 'Baja despacio a la plancha sin hundir la cadera.']::text[], array['Doblar las rodillas (eso es otro ejercicio).', 'Hundir la cadera al volver.', 'Manos por delante de los hombros.']::text[]),
  ('trx_y_raise', array['Coge las asas y camina hacia delante hasta inclinarte un poco atrás.', 'Con los brazos estirados, súbelos en diagonal hasta formar una Y por encima de la cabeza.', 'Baja despacio sin dejar caer el cuerpo.']::text[], array['Doblar los codos.', 'Encoger los hombros.', 'Arquear la lumbar.']::text[]),
  ('trx_biceps_curl', array['Coge las asas con las palmas hacia arriba y camina hasta inclinarte atrás.', 'Sube los codos a la altura de los hombros con los brazos estirados.', 'Dobla los codos llevando las manos hacia la frente sin bajar los codos.', 'Vuelve despacio a brazos estirados.']::text[], array['Bajar los codos durante el curl.', 'Hundir la cadera.', 'Usar impulso.']::text[]),
  ('band_pull_apart', array['Coge una goma con los brazos estirados al frente, a la altura de los hombros.', 'Ábrela llevando las manos hacia los lados hasta que toque el pecho.', 'Junta los omóplatos un segundo y vuelve despacio.']::text[], array['Doblar los codos.', 'Encoger los hombros.', 'Arquear la espalda para abrir más.']::text[]),
  ('banded_lateral_walk', array['Coloca una mini band por encima de las rodillas o en los tobillos.', 'Baja a media sentadilla con el pecho alto.', 'Da pasos laterales cortos sin juntar del todo los pies.', 'Haz las mismas repeticiones hacia los dos lados.']::text[], array['Dejar que las rodillas se cierren.', 'Levantarse de la semisentadilla.', 'Balancear el tronco en cada paso.']::text[]),
  ('band_row', array['Ancla la goma a la altura del pecho o pásala por los pies sentado.', 'Con la espalda recta, coge los extremos con los brazos estirados.', 'Tira llevando los codos atrás y juntando los omóplatos.', 'Vuelve despacio resistiendo la goma.']::text[], array['Echar el tronco atrás para tirar.', 'Soltar la goma de golpe.', 'Encoger los hombros.']::text[]),
  ('band_external_rotation', array['Ancla la goma a la altura del codo y ponte de lado.', 'Codo pegado al costado y doblado a 90° (una toalla entre codo y cuerpo ayuda).', 'Gira el antebrazo hacia fuera sin despegar el codo y vuelve despacio.']::text[], array['Separar el codo del cuerpo.', 'Girar el tronco en vez del brazo.', 'Goma demasiado fuerte.']::text[]),
  ('band_kickback', array['Ponte a cuatro patas con la goma por la planta de un pie y sujeta en las manos.', 'Empuja ese pie hacia atrás y arriba apretando el glúteo.', 'Vuelve despacio sin arquear la lumbar; termina un lado y cambia.']::text[], array['Arquear la lumbar para subir más.', 'Girar la cadera hacia fuera.', 'Ir con impulso.']::text[])
) as v (id, steps, mistakes)
where e.id = v.id and e.owner_id is null;
